package compose

import "github.com/ui8kit/codegen/generated/templ/ui/select"

// SelectProps: Select: Select + recipe select.
type SelectProps struct {
	Size string
	Variant string
	State string
	selectfield.SelectProps
}

func selectInner(p SelectProps) selectfield.SelectProps {
	in := p.SelectProps
	in.Class = Join(Rc("select", map[string]string{"size": p.Size, "variant": p.Variant, "state": p.State}), p.SelectProps.Class)
	if p.State == "error" {
		in.AriaInvalid = Or(in.AriaInvalid, "true")
	}
	return in
}

// Select renders Select with the composition classes.
templ Select(p SelectProps) {
	@selectfield.Select(selectInner(p)) {
		{ children... }
	}
}
